BEGIN
  -- ── Décor ───────────────────────────────────────────────────────────
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  INSERT INTO public.network_administrators (user_id, status) VALUES (v_admin, 'active');
  INSERT INTO public.catalog_ref_source_partners (code, label, sort_order, is_active)
  VALUES ('other_partner', 'Outro parceiro', 80, true) ON CONFLICT (code) DO NOTHING;
  UPDATE public.libraries SET tombo_pattern = '{"prefix": "L3-T-", "year": false, "pad": 4}'::jsonb WHERE id = v_lib;
  INSERT INTO public.libraries (id, slug, name, is_active, visibility_level, tombo_pattern)
  VALUES (gen_random_uuid(), 'essai-h21-l3-b', 'Essai H21 lot 3 — B', true, 'private',
          '{"prefix": "L3B-T-", "year": false, "pad": 4}'::jsonb)
  RETURNING id INTO v_libB;
  -- 4444… : coordination de B (sa seule adhésion active et principale)
  UPDATE public.user_library_memberships SET status = 'inactive', is_primary = false WHERE user_id = v_coordB;
  INSERT INTO public.user_library_memberships (user_id, library_id, role, status, is_primary)
  VALUES (v_coordB, v_libB, 'coordenador', 'active', true);

  INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
  VALUES ('L3 PMB 8.1 (fixtures)', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_src;

  -- Premier import : promu, révisé, publié (les bases du lot 2).
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l3-pmb.iso', 'l3-pmb.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run1;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run1, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'new_record', 'accept_new'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  v_res := public.fn_import_promote(v_run1, ARRAY['new_record'], ARRAY['accept_new']);
  v_lot1 := (v_res->>'batch_id')::bigint;
  UPDATE public.book_drafts SET bib_ref = 'L3-PMB-REF-' || id WHERE batch_id = v_lot1 AND bib_ref IS NULL;
  v_res := public.fn_batch_review_request(v_lot1);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  PERFORM public.publish_catalog_batch(v_lot1);
  IF (SELECT count(*) FROM public.book_drafts WHERE batch_id = v_lot1 AND status = 'published') <> 64
     OR (SELECT count(*) FROM ingest.book_import_baselines bl JOIN public.book_external_ids e ON e.id = bl.external_id_id
          WHERE e.scheme = 'import:' || v_src) <> 64 THEN
    RAISE EXCEPTION 'decor : publication ou bases incompletes';
  END IF;

  -- Les notices publiées, par rang du fichier.
  SELECT max(d.published_book_id) FILTER (WHERE s.row_no = 1),  max(d.published_book_id) FILTER (WHERE s.row_no = 2),
         max(d.published_book_id) FILTER (WHERE s.row_no = 6),  max(d.published_book_id) FILTER (WHERE s.row_no = 48),
         max(d.published_book_id) FILTER (WHERE s.row_no = 49), max(d.published_book_id) FILTER (WHERE s.row_no = 51),
         max(d.published_book_id) FILTER (WHERE s.row_no = 52), max(d.published_book_id) FILTER (WHERE s.row_no = 53),
         max(d.published_book_id) FILTER (WHERE s.row_no = 54), max(d.published_book_id) FILTER (WHERE s.row_no = 55),
         max(d.published_book_id) FILTER (WHERE s.row_no = 56), max(d.published_book_id) FILTER (WHERE s.row_no = 58),
         max(d.published_book_id) FILTER (WHERE s.row_no = 59), max(d.published_book_id) FILTER (WHERE s.row_no = 60)
    INTO b1, b2, b6, b48, b49, b51, b52, b53, b54, b55, b56, b58, b59, b60
    FROM ingest.partner_catalog_staging_rows s
    JOIN ingest.partner_catalog_row_to_draft m ON m.staging_row_id = s.id
    JOIN public.book_drafts d ON d.id = m.draft_id
   WHERE s.run_id = v_run1;

  -- ── Retouches dans AnarBib (après la publication, avant le réimport) ──
  SELECT editora INTO v_editora49 FROM public.books WHERE id = b49;
  UPDATE public.books SET editora = 'L3 Editora local' WHERE id = b49;                         -- local_seul
  UPDATE public.books SET ano = '1902' WHERE id = b51;                                         -- conflit
  UPDATE public.books SET edicao = 'L3 2e ed.' WHERE id = b52;                                 -- identique
  UPDATE public.books SET autor = 'L3 Quelqu''un d''autre' WHERE id = b56;                     -- autor seul
  UPDATE public.book_contributors SET name = 'L3 Nom corrige' WHERE book_id = b58 AND position = 1;  -- local_seul
  UPDATE public.books SET titulo = '  ' || titulo || '  ', subtitulo = coalesce(subtitulo, '') WHERE id = b60;  -- normalisation
  -- sans_base : la base de la ligne 54 supprimée ; celle de la ligne 55 reprise à champs douteux
  DELETE FROM ingest.book_import_baselines bl USING public.book_external_ids e
   WHERE e.id = bl.external_id_id AND e.book_id = b54 AND e.library_id = v_lib;
  UPDATE ingest.book_import_baselines bl SET origine = 'reprise', reprise_champs_douteux = ARRAY['cdd', 'notas']
    FROM public.book_external_ids e WHERE e.id = bl.external_id_id AND e.book_id = b55 AND e.library_id = v_lib;
  -- vedettes cataloguées (thésaurus) pour les lignes 6 et 19 : la comparaison les ignore (IMP-30)
  INSERT INTO public.subjects (slug, label_i18n, status)
  SELECT 'l3-sujet-a', jsonb_build_object('fr', upper(s.subjects->>0), 'pt-BR', 'L3 rótulo A'), 'ativo'
    FROM ingest.partner_catalog_staging_rows s WHERE s.run_id = v_run1 AND s.row_no = 6
  RETURNING id INTO v_s1;
  INSERT INTO public.subjects (slug, label_i18n, alt_i18n, status)
  SELECT 'l3-sujet-b', jsonb_build_object('pt-BR', 'L3 rótulo B'), jsonb_build_object('fr', jsonb_build_array(s.subjects->>1)), 'ativo'
    FROM ingest.partner_catalog_staging_rows s WHERE s.run_id = v_run1 AND s.row_no = 6
  RETURNING id INTO v_s2;
  INSERT INTO public.book_subjects (book_id, subject_id, ord) VALUES (b6, v_s2, 1), (b6, v_s1, 2);
  -- ligne 19 : UNE vedette du thésaurus porte les deux chaînes du fichier
  -- (étiquette et étiquette alternative) : l'ensemble vaut, pas l'affichage
  INSERT INTO public.subjects (slug, label_i18n, alt_i18n, status)
  SELECT 'l3-sujet-c', jsonb_build_object('fr', s.subjects->>0), jsonb_build_object('fr', jsonb_build_array(s.subjects->>1)), 'ativo'
    FROM ingest.partner_catalog_staging_rows s WHERE s.run_id = v_run1 AND s.row_no = 19
  RETURNING id INTO v_k;
  INSERT INTO public.book_subjects (book_id, subject_id, ord)
  SELECT d.published_book_id, v_k, 1
    FROM ingest.partner_catalog_staging_rows s
    JOIN ingest.partner_catalog_row_to_draft m ON m.staging_row_id = s.id
    JOIN public.book_drafts d ON d.id = m.draft_id
   WHERE s.run_id = v_run1 AND s.row_no = 19;
  -- la bibliothèque B porte la même clé que la ligne 54 sur la même notice, avec
  -- une base : celle de BLMF absente, la ligne reste sans base (jamais celle de B)
  INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
  VALUES ('L3 PMB de B', v_libB, 'mapeada', 'own_catalog', true) RETURNING id INTO v_srcP;
  INSERT INTO public.book_external_ids (book_id, library_id, scheme, value, source_id)
  VALUES (b54, v_libB, 'import:' || v_srcP, '64', v_srcP);
  INSERT INTO ingest.book_import_baselines (external_id_id, mapped, contributors, subjects, mapping_version, payload_hash, origine)
  SELECT e.id, f.v->'mapped', f.v->'contributors', f.v->'subjects', f.v->>'mapping_version', f.v->>'payload_hash', 'import'
    FROM public.book_external_ids e
    CROSS JOIN LATERAL (SELECT ingest.fn_import_row_as_book(s, '{}'::jsonb) AS v
                          FROM ingest.partner_catalog_staging_rows s WHERE s.run_id = v_run1 AND s.row_no = 54) f
   WHERE e.book_id = b54 AND e.library_id = v_libB;
  v_srcP := NULL;

  -- ── Le réimport : les mêmes lignes, retouchées dans le fichier ─────────
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l3-pmb-reimport.iso', 'l3-pmb-reimport.iso', 'marc_iso2709', 'parsed') RETURNING id INTO v_run2;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run2, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'unreviewed', 'pending'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  SELECT max(id) FILTER (WHERE row_no = 1),  max(id) FILTER (WHERE row_no = 2),  max(id) FILTER (WHERE row_no = 6),
         max(id) FILTER (WHERE row_no = 48), max(id) FILTER (WHERE row_no = 49), max(id) FILTER (WHERE row_no = 51),
         max(id) FILTER (WHERE row_no = 52), max(id) FILTER (WHERE row_no = 53), max(id) FILTER (WHERE row_no = 54),
         max(id) FILTER (WHERE row_no = 55), max(id) FILTER (WHERE row_no = 56), max(id) FILTER (WHERE row_no = 58),
         max(id) FILTER (WHERE row_no = 59), max(id) FILTER (WHERE row_no = 60), max(id) FILTER (WHERE row_no = 19)
    INTO r1, r2, r6, r48, r49, r51, r52, r53, r54, r55, r56, r58, r59, r60, r19
    FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2;
  UPDATE ingest.partner_catalog_staging_rows SET publication_year = '2009' WHERE id = r48;               -- source_seule
  UPDATE ingest.partner_catalog_staging_rows SET publication_year = '1903' WHERE id = r51;               -- conflit
  UPDATE ingest.partner_catalog_staging_rows SET edition_statement = 'L3 2e ed.' WHERE id = r52;         -- identique
  UPDATE ingest.partner_catalog_staging_rows SET title = title || ' (L3)' WHERE id = r54;                -- sans base
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{classification}', '"320"') WHERE id = r55;  -- cdd douteux
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{contributors,0,name}', '"L3 Nom du fichier"') WHERE id = r59;
  UPDATE ingest.partner_catalog_staging_rows SET subjects = '["L3 Nouvelle vedette"]'::jsonb WHERE id = r2;
  -- deux lignes porteront un exemplaire neuf (le rapprochement de T13)
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', jsonb_build_array(jsonb_build_object('code', 'L3-NOUVEAU-' || row_no)))
   WHERE id IN (r48, r51);

  -- L'empreinte du catalogue (T8), juste avant le rapprochement.
  v_ref := 'select md5(concat_ws(''|'',
      (select string_agg(md5(to_jsonb(b)::text), '','' order by b.id) from public.books b),
      (select string_agg(md5(to_jsonb(c)::text), '','' order by c.id) from public.book_contributors c),
      (select string_agg(bs.book_id || '':'' || bs.subject_id || '':'' || bs.ord, '','' order by bs.book_id, bs.subject_id) from public.book_subjects bs),
      (select string_agg(md5(to_jsonb(d)::text), '','' order by d.id) from public.book_drafts d),
      (select string_agg(md5(to_jsonb(e)::text), '','' order by e.id) from public.exemplares e),
      (select string_agg(md5(to_jsonb(x)::text), '','' order by x.id) from public.exemplar_drafts x),
      (select string_agg(md5(to_jsonb(k)::text), '','' order by k.id) from public.catalog_batches k)))';
  EXECUTE v_ref INTO v_avant;

  -- ── T1 ──────────────────────────────────────────────────────────────
  v_t := 'T1 reimport : 64 known_record, rien de calcule au rapprochement ; recalcul par pages : 64 comparaisons stockees';
  DECLARE v_ids bigint[]; v_p1 jsonb; v_p2 jsonb;
  BEGIN
    v_res := ingest.fn_match_partner_catalog_run(v_run2);
    SELECT array_agg(id ORDER BY id) INTO v_ids
      FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND match_status = 'known_record';
    v_n := (SELECT count(*) FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND comparaison IS NOT NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_p1 := public.fn_import_recomparer(v_run2, v_ids[1:32]);
    v_p2 := public.fn_import_recomparer(v_run2, v_ids[33:64]);
    EXECUTE 'RESET ROLE';
    IF cardinality(v_ids) = 64 AND v_n = 0 AND (v_res->>'comparaisons_effacees')::int = 0 AND NOT (v_res ? 'comparaisons')
       AND (v_p1->>'compared_rows')::int = 32 AND (v_p2->>'compared_rows')::int = 32
       AND jsonb_array_length(v_p1->'rows') = 32
       AND (SELECT bool_and(r->'counts' = sr.comparaison->'counts') FROM jsonb_array_elements(v_p1->'rows') r
              JOIN ingest.partner_catalog_staging_rows sr ON sr.id = (r->>'id')::bigint)
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2
             AND jsonb_array_length(comparaison->'champs') = 24 AND comparaison_at IS NOT NULL
             AND comparaison->>'version' = 'h21-lot3/2026-10-05'
             AND (comparaison->>'book_id')::bigint = proposed_book_id) = 64
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : avant='||coalesce(v_n::text,'∅')||' rapprochement='||coalesce(v_res::text, 'NULL')
         ||' pages='||coalesce(v_p1->>'compared_rows','∅')||'/'||coalesce(v_p2->>'compared_rows','∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T2 ──────────────────────────────────────────────────────────────
  v_t := 'T2 verdicts exacts : source_seule, local_seul, conflit, identique, inchange (et leurs valeurs)';
  BEGIN
    SELECT string_agg(x, ' ' ORDER BY x) INTO v_txt FROM (
      SELECT sr.row_no || ':' || (c->>'champ') || '=' || (c->>'verdict') AS x
        FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
       WHERE sr.id IN (r48, r49, r51, r52, r53) AND c->>'verdict' <> 'inchange') q;
    IF v_txt = '48:ano=source_seule 49:editora=local_seul 51:ano=conflit 52:edicao=identique'
       AND (SELECT (comparaison->'counts')::text FROM ingest.partner_catalog_staging_rows WHERE id = r53)
           = '{"conflit": 0, "inchange": 24, "identique": 0, "sans_base": 0, "local_seul": 0, "source_seule": 0}'
       AND (SELECT (comparaison->'counts')::text FROM ingest.partner_catalog_staging_rows WHERE id = r48)
           = '{"conflit": 0, "inchange": 23, "identique": 0, "sans_base": 0, "local_seul": 0, "source_seule": 1}'
       -- les trois valeurs : B, A, N
       AND (SELECT c FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r51 AND c->>'champ' = 'ano')
           = jsonb_build_object('champ', 'ano', 'verdict', 'conflit', 'b', '2023', 'a', '1902', 'n', '1903')
       AND (SELECT c FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r48 AND c->>'champ' = 'ano')
           = jsonb_build_object('champ', 'ano', 'verdict', 'source_seule', 'b', '2008', 'a', '2008', 'n', '2009')
       AND (SELECT c FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r49 AND c->>'champ' = 'editora')
           = jsonb_build_object('champ', 'editora', 'verdict', 'local_seul', 'b', v_editora49, 'a', 'L3 Editora local', 'n', v_editora49)
       AND (SELECT c FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r52 AND c->>'champ' = 'edicao')
           = jsonb_build_object('champ', 'edicao', 'verdict', 'identique', 'b', NULL, 'a', 'L3 2e ed.', 'n', 'L3 2e ed.')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_txt, 'NULL')||' ; 51 ano '
         ||coalesce((SELECT c::text FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
                      WHERE sr.id = r51 AND c->>'champ' = 'ano'), '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T3 ──────────────────────────────────────────────────────────────
  v_t := 'T3 sans_base : base absente ; base reprise a champs douteux (jamais source_seule)';
  BEGIN
    SELECT string_agg(sr.row_no || ':' || (c->>'champ') || '=' || (c->>'verdict'), ' ' ORDER BY sr.row_no, c->>'champ') INTO v_txt
      FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
     WHERE sr.id IN (r54, r55) AND c->>'verdict' NOT IN ('inchange', 'identique');
    IF v_txt = '54:titulo=sans_base 55:cdd=sans_base'
       AND (SELECT (comparaison->'counts')::text FROM ingest.partner_catalog_staging_rows WHERE id = r54)
           = '{"conflit": 0, "inchange": 0, "identique": 23, "sans_base": 1, "local_seul": 0, "source_seule": 0}'
       AND (SELECT comparaison->>'baseline_id' FROM ingest.partner_catalog_staging_rows WHERE id = r54) IS NULL
       AND (SELECT (comparaison->'counts')::text FROM ingest.partner_catalog_staging_rows WHERE id = r55)
           = '{"conflit": 0, "inchange": 22, "identique": 1, "sans_base": 1, "local_seul": 0, "source_seule": 0}'
       AND (SELECT c->>'verdict' FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r55 AND c->>'champ' = 'notas') = 'identique'
       AND (SELECT c FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r55 AND c->>'champ' = 'cdd') = jsonb_build_object('champ', 'cdd', 'verdict', 'sans_base', 'b', NULL, 'a', NULL, 'n', '320')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_txt, 'NULL')||' ; 54 '
         ||coalesce((SELECT (comparaison->'counts')::text FROM ingest.partner_catalog_staging_rows WHERE id = r54), '∅')||' ; 55 '
         ||coalesce((SELECT (comparaison->'counts')::text FROM ingest.partner_catalog_staging_rows WHERE id = r55), '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T4 ──────────────────────────────────────────────────────────────
  v_t := 'T4 responsabilites par book_contributors (jamais books.autor) : autor seul -> rien ; AnarBib -> local_seul ; fichier -> source_seule';
  BEGIN
    SELECT string_agg(sr.row_no || ':' || (c->>'champ') || '=' || (c->>'verdict'), ' ' ORDER BY sr.row_no, c->>'champ') INTO v_txt
      FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
     WHERE sr.id IN (r56, r58, r59) AND c->>'verdict' <> 'inchange';
    IF v_txt = '58:contributors=local_seul 59:contributors=source_seule'
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
                        WHERE sr.run_id = v_run2 AND c->>'champ' = 'autor')
       AND (SELECT c->'a'->0->>0 FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r58 AND c->>'champ' = 'contributors') = 'L3 Nom corrige'
       AND (SELECT c->'n'->0->>0 FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r59 AND c->>'champ' = 'contributors') = 'L3 Nom du fichier'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_txt, 'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T5 ──────────────────────────────────────────────────────────────
  v_t := 'T5 normalisation : espaces en bord et chaine vide ne sont pas des modifications';
  BEGIN
    IF (SELECT (comparaison->'counts'->>'inchange')::int FROM ingest.partner_catalog_staging_rows WHERE id = r60) = 24
       AND (SELECT titulo <> btrim(titulo) AND subtitulo = '' FROM public.books WHERE id = b60)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '
         ||coalesce((SELECT string_agg(c->>'champ' || '=' || (c->>'verdict'), ' ') FROM ingest.partner_catalog_staging_rows sr,
                      jsonb_array_elements(sr.comparaison->'champs') c WHERE sr.id = r60 AND c->>'verdict' <> 'inchange'), '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T6 ──────────────────────────────────────────────────────────────
  v_t := 'T6 IMP-30 : vedettes non comparees ; une vedette changee seule ne se voit que par notas (source_seule)';
  BEGIN
    SELECT string_agg(sr.row_no || ':' || (c->>'champ') || '=' || (c->>'verdict'), ' ' ORDER BY sr.row_no, c->>'champ') INTO v_txt
      FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
     WHERE sr.id IN (r1, r2, r6, r19) AND c->>'verdict' <> 'inchange';
    IF v_txt = '2:notas=source_seule'
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
                        WHERE sr.run_id = v_run2 AND c->>'champ' = 'subjects')
       AND (SELECT (comparaison->'counts')::text FROM ingest.partner_catalog_staging_rows WHERE id = r2)
           = '{"conflit": 0, "inchange": 23, "identique": 0, "sans_base": 0, "local_seul": 0, "source_seule": 1}'
       AND (SELECT c->>'n' LIKE '%Assuntos importados: L3 Nouvelle vedette%' AND c->>'b' NOT LIKE '%L3 Nouvelle vedette%'
              FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
             WHERE sr.id = r2 AND c->>'champ' = 'notas')
       -- des vedettes cataloguées (lignes 6 et 19) ne changent rien
       AND (SELECT count(*) FROM public.book_subjects WHERE book_id = b6) = 2
       AND (SELECT min((comparaison->'counts'->>'inchange')::int) FROM ingest.partner_catalog_staging_rows WHERE id IN (r1, r6, r19)) = 24
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_txt, 'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T7 ──────────────────────────────────────────────────────────────
  v_t := 'T7 reimport a l''identique propre : lignes non retouchees, tout inchange';
  BEGIN
    SELECT count(DISTINCT sr.id),
           string_agg(DISTINCT sr.row_no || ':' || (c->>'champ') || '=' || (c->>'verdict'), ' ')
             FILTER (WHERE c->>'verdict' <> 'inchange')
      INTO v_n, v_txt
      FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
     WHERE sr.run_id = v_run2 AND sr.id NOT IN (r1, r2, r6, r48, r49, r51, r52, r53, r54, r55, r56, r58, r59, r60, r19);
    IF v_n = 49 AND v_txt IS NULL
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||v_n||' lignes ; ecarts : '||left(coalesce(v_txt, '-'), 600)); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T9 ──────────────────────────────────────────────────────────────
  v_t := 'T9 fn_import_row_comparison : coordination et administration lisent ; lectrice, autre bibliotheque, autre run refuses';
  DECLARE v_e_lect text; v_e_b text; v_e_run text; v_adm jsonb;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_cmp := public.fn_import_row_comparison(v_run2, r51);
    BEGIN PERFORM public.fn_import_row_comparison(v_run1, r51); v_e_run := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_e_run := SQLERRM; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_lect, 'role', 'authenticated')::text, true);
    BEGIN PERFORM public.fn_import_row_comparison(v_run2, r51); v_e_lect := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_e_lect := SQLERRM; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
    BEGIN PERFORM public.fn_import_row_comparison(v_run2, r51); v_e_b := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_e_b := SQLERRM; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    v_adm := public.fn_import_row_comparison(v_run2, r51);
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF jsonb_array_length(v_cmp->'champs') = 24
       AND (v_cmp->'counts'->>'conflit')::int = 1 AND (v_cmp->>'book_id')::bigint = b51
       AND (v_cmp->>'baseline_id') IS NOT NULL AND v_cmp->>'match_status' = 'known_record'
       AND (SELECT c FROM jsonb_array_elements(v_cmp->'champs') c WHERE c->>'champ' = 'ano')
           = jsonb_build_object('champ', 'ano', 'verdict', 'conflit', 'b', '2023', 'a', '1902', 'n', '1903')
       AND v_cmp->'champs' = (SELECT comparaison->'champs' FROM ingest.partner_catalog_staging_rows WHERE id = r51)
       AND v_adm = v_cmp
       AND v_e_lect = 'Acesso bibliotecario obrigatorio.'
       AND v_e_b = format('Run %s introuvable', v_run2)
       AND v_e_run = format('Linha %s introuvable', r51)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : lectrice='||coalesce(v_e_lect,'∅')||' B='||coalesce(v_e_b,'∅')
         ||' run='||coalesce(v_e_run,'∅')||' admin='||coalesce(left(v_adm::text, 80),'∅')||' coord='||coalesce(left(v_cmp::text, 200),'∅')); END IF;
  EXCEPTION WHEN OTHERS THEN
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T10 ─────────────────────────────────────────────────────────────
  v_t := 'T10 fn_import_recomparer : coordination ou administration de la bibliotheque du run ; la selection seule ; le stocke suit la notice';
  DECLARE v_e_lect text; v_e_b text; v_adm jsonb; v_e_adm text; v_e_bib text; v_lu jsonb;
  BEGIN
    SELECT comparaison_at INTO v_at FROM ingest.partner_catalog_staging_rows WHERE id = r51;
    SELECT comparaison_at INTO v_at2 FROM ingest.partner_catalog_staging_rows WHERE id = r49;
    UPDATE public.books SET editora = v_editora49 WHERE id = b49;      -- AnarBib revient à la base
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_lect, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_recomparer(v_run2, ARRAY[r49]); v_e_lect := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_e_lect := SQLERRM; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
    BEGIN PERFORM public.fn_import_recomparer(v_run2, ARRAY[r49]); v_e_b := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_e_b := SQLERRM; END;
    -- l'administration sans bibliothèque active : refusée (comme fn_import_set_editorial)
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    BEGIN PERFORM public.fn_import_recomparer(v_run2, ARRAY[r53]); v_e_adm := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_e_adm := SQLERRM; END;
    EXECUTE 'RESET ROLE';
    -- la lectrice devient librarian de BLMF : elle lit le détail, ne recalcule pas
    UPDATE public.user_library_memberships SET role = 'librarian' WHERE user_id = v_lect AND library_id = v_lib;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_lect, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_lu := public.fn_import_row_comparison(v_run2, r53);
    BEGIN PERFORM public.fn_import_recomparer(v_run2, ARRAY[r53]); v_e_bib := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_e_bib := SQLERRM; END;
    EXECUTE 'RESET ROLE';
    UPDATE public.user_library_memberships SET role = 'reader' WHERE user_id = v_lect AND library_id = v_lib;
    -- l'administration, avec BLMF pour bibliothèque active : acceptée
    INSERT INTO public.user_library_memberships (user_id, library_id, role, status, is_primary)
    VALUES (v_admin, v_lib, 'librarian', 'active', true);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_adm := public.fn_import_recomparer(v_run2, ARRAY[r53]);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_res := public.fn_import_recomparer(v_run2, ARRAY[r49]);
    EXECUTE 'RESET ROLE';
    -- le N gardé ne sert que si la ligne n'a pas changé : le fichier de la
    -- ligne 52 dit désormais autre chose (une ligne n'est jamais réécrite
    -- ainsi par l'application ; on simule une relecture qui l'aurait changée)
    UPDATE ingest.partner_catalog_staging_rows SET edition_statement = 'L3 3e ed.' WHERE id = r52;
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r52]);
    UPDATE ingest.partner_catalog_staging_rows SET edition_statement = 'L3 2e ed.' WHERE id = r52;
    SELECT c->>'verdict' || '/' || (c->>'n') INTO v_txt2
      FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
     WHERE sr.id = r52 AND c->>'champ' = 'edicao';
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r52]);
    -- de même la base : changée après le stockage, elle est relue
    UPDATE ingest.book_import_baselines bl SET mapped = jsonb_set(bl.mapped, '{volume}', '"L3 tome base"')
      FROM public.book_external_ids e WHERE e.id = bl.external_id_id AND e.book_id = b56 AND e.library_id = v_lib;
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r56]);
    SELECT c->>'verdict' INTO v_hint
      FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
     WHERE sr.id = r56 AND c->>'champ' = 'volume';
    UPDATE ingest.book_import_baselines bl SET mapped = bl.mapped - 'volume' || jsonb_build_object('volume', NULL)
      FROM public.book_external_ids e WHERE e.id = bl.external_id_id AND e.book_id = b56 AND e.library_id = v_lib;
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r56]);
    IF v_hint IS DISTINCT FROM 'identique'
       OR (SELECT (comparaison->'counts'->>'inchange')::int FROM ingest.partner_catalog_staging_rows WHERE id = r56) <> 24 THEN
      v_e_b := v_e_b || ' ; B garde perime : ' || coalesce(v_hint, '∅');
    END IF;
    IF v_txt2 IS DISTINCT FROM 'conflit/L3 3e ed.'
       OR (SELECT c->>'verdict' FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.comparaison->'champs') c
            WHERE sr.id = r52 AND c->>'champ' = 'edicao') IS DISTINCT FROM 'identique' THEN
      v_e_b := v_e_b || ' ; N garde perime : ' || coalesce(v_txt2, '∅');
    END IF;
    IF v_e_lect = 'Acesso bibliotecario obrigatorio.'
       AND v_e_b = format('Run %s introuvable', v_run2)
       AND v_e_adm = 'Acesso bibliotecario obrigatorio.'
       AND v_e_bib = 'Acesso restrito ao coordenador da biblioteca.'
       AND jsonb_array_length(v_lu->'champs') = 24
       AND (v_adm->>'compared_rows')::int = 1
       AND (v_res->>'compared_rows')::int = 1 AND (v_res->'counts'->>'inchange')::int = 24
       AND (SELECT (comparaison->'counts'->>'inchange')::int FROM ingest.partner_catalog_staging_rows WHERE id = r49) = 24
       -- hors sélection : intouchée
       AND (SELECT comparaison_at FROM ingest.partner_catalog_staging_rows WHERE id = r51) = v_at
       AND (SELECT comparaison_at FROM ingest.partner_catalog_staging_rows WHERE id = r49) > v_at2
       AND (SELECT (comparaison->'counts'->>'conflit')::int FROM ingest.partner_catalog_staging_rows WHERE id = r51) = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : lectrice='||coalesce(v_e_lect,'∅')||' B='||coalesce(v_e_b,'∅')
         ||' admin sans biblio='||coalesce(v_e_adm,'∅')||' librarian='||coalesce(v_e_bib,'∅')
         ||' admin='||coalesce(left(v_adm::text, 120),'∅')||' coord='||coalesce(left(v_res::text, 120),'∅')); END IF;
  EXCEPTION WHEN OTHERS THEN
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T12 ─────────────────────────────────────────────────────────────
  v_t := 'T12 fn_import_list_run_rows : comparison_counts = le stocke, NULL hors known_record, colonne a la fin';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT jsonb_agg(jsonb_build_object('id', l.id, 'row_no', l.row_no, 'ms', l.match_status, 'cc', l.comparison_counts))
      INTO v_res FROM public.fn_import_list_run_rows(v_run2) l;
    EXECUTE 'RESET ROLE';
    SELECT string_agg((l->>'row_no') || '=' || coalesce(l->'cc'->>'conflit', 'null') || '/' || coalesce(l->'cc'->>'source_seule', 'null'),
                      ' ' ORDER BY (l->>'row_no')::int),
           bool_and((l->'cc') IS NOT DISTINCT FROM sr.comparaison->'counts' AND l->'cc' IS NOT NULL AND jsonb_typeof(l->'cc') = 'object')
      INTO v_txt, v_ok
      FROM jsonb_array_elements(v_res) l
      JOIN ingest.partner_catalog_staging_rows sr ON sr.id = (l->>'id')::bigint
     WHERE l->>'ms' = 'known_record';
    IF v_txt LIKE '%48=0/1 %' AND v_txt LIKE '%51=1/0 %' AND v_txt LIKE '%53=0/0 %' AND v_txt LIKE '%56=0/0 %'
       AND v_ok
       AND (SELECT (p.proargnames)[34] = 'comparison_counts' AND (p.proargnames)[33] = 'proposed_book_held'
                   -- 06/10/2026 (H21 lot 4) : trois colonnes ajoutées après
                   -- comparison_counts ; elle reste la 34e
                   AND array_length(p.proargnames, 1) >= 34
              FROM pg_proc p WHERE p.oid = 'public.fn_import_list_run_rows(bigint)'::regprocedure)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce(v_txt, 'NULL'), 300)||' ok='||coalesce(v_ok::text,'∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T12 bis (la ligne au statut changé à la main) ───────────────────
  v_t := 'T12b la liste tait la comparaison d''une ligne qui n''est plus known_record, ou faite contre une autre notice (fusion)';
  DECLARE v_ok2 boolean;
  BEGIN
    UPDATE ingest.partner_catalog_staging_rows SET match_status = 'manual_decision' WHERE id = r56;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT l.comparison_counts IS NULL INTO v_ok FROM public.fn_import_list_run_rows(v_run2) l WHERE l.id = r56;
    EXECUTE 'RESET ROLE';
    UPDATE ingest.partner_catalog_staging_rows SET match_status = 'known_record' WHERE id = r56;
    -- une fusion de notices déplace la notice proposée : la comparaison stockée est périmée
    UPDATE ingest.partner_catalog_staging_rows SET proposed_book_id = b49 WHERE id = r56;
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT l.comparison_counts IS NULL INTO v_ok2 FROM public.fn_import_list_run_rows(v_run2) l WHERE l.id = r56;
    EXECUTE 'RESET ROLE';
    UPDATE ingest.partner_catalog_staging_rows SET proposed_book_id = b56 WHERE id = r56;
    IF v_ok AND v_ok2 AND (SELECT comparaison IS NOT NULL FROM ingest.partner_catalog_staging_rows WHERE id = r56)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : statut='||coalesce(v_ok::text, 'NULL')||' fusion='||coalesce(v_ok2::text, 'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T8 ──────────────────────────────────────────────────────────────
  -- (après T1, T9, T10, T12 : rapprochement, détail, recalcul, liste ; plus la
  -- comparaison elle-même ; la seule retouche du catalogue entre les deux
  -- empreintes est celle de T10, défaite ici pour comparer.)
  v_t := 'T8 aucune ecriture au catalogue : empreinte inchangee (books, responsabilites, vedettes, brouillons, exemplaires, lots)';
  BEGIN
    PERFORM count(*) FROM ingest.fn_import_trois_etats(v_run2);
    UPDATE public.books SET editora = 'L3 Editora local' WHERE id = b49;      -- la retouche de T10 défaite
    EXECUTE v_ref INTO v_apres;
    IF v_apres = v_avant
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : empreinte changee'); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T11 ─────────────────────────────────────────────────────────────
  v_t := 'T11 relecture du run : rien de calcule, une ligne qui n''est plus reconnue perd sa comparaison ; le recalcul remet a jour';
  DECLARE v_avant_49 text; v_ids bigint[];
  BEGIN
    -- r49 : AnarBib retouchée (T8) mais le stocké dit « inchange » (T10)
    DELETE FROM public.book_external_ids WHERE book_id = b53 AND library_id = v_lib;   -- r53 ne sera plus reconnue
    v_res := ingest.fn_match_partner_catalog_run(v_run2);
    SELECT (comparaison->'counts')::text INTO v_avant_49 FROM ingest.partner_catalog_staging_rows WHERE id = r49;
    SELECT array_agg(id ORDER BY id) INTO v_ids
      FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND match_status = 'known_record';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res2 := public.fn_import_recomparer(v_run2, v_ids);
    EXECUTE 'RESET ROLE';
    -- le recalcul efface aussi, dans sa sélection, une comparaison restée sur une
    -- ligne qui n'est plus reconnue (posée ici à la main)
    UPDATE ingest.partner_catalog_staging_rows SET comparaison = '{"version": "perimee"}'::jsonb, comparaison_at = now() WHERE id = r53;
    EXECUTE 'SET LOCAL ROLE authenticated';
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r53]);
    EXECUTE 'RESET ROLE';
    IF (v_res->>'comparaisons_effacees')::int = 1
       AND v_avant_49 = '{"conflit": 0, "inchange": 24, "identique": 0, "sans_base": 0, "local_seul": 0, "source_seule": 0}'
       AND (SELECT match_status <> 'known_record' AND comparaison IS NULL AND comparaison_at IS NULL
              FROM ingest.partner_catalog_staging_rows WHERE id = r53)
       AND (v_res2->>'compared_rows')::int = 63
       AND (SELECT (comparaison->'counts'->>'local_seul')::int FROM ingest.partner_catalog_staging_rows WHERE id = r49) = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : effacees='||coalesce(v_res->>'comparaisons_effacees', '∅')
         ||' ; 49 avant='||coalesce(v_avant_49, '∅')
         ||' ; 53 '||coalesce((SELECT match_status || ' ' || coalesce((comparaison->'counts')::text, 'NULL') FROM ingest.partner_catalog_staging_rows WHERE id = r53), '∅')
         ||' ; recalcul='||coalesce(v_res2->>'compared_rows', '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T13 ─────────────────────────────────────────────────────────────
  v_t := 'T13 rapport de revision : la cle updates (comptes, exemples, conflits d''abord) ; absente sans ligne reconnue';
  DECLARE v_rap jsonb; v_rap1 jsonb;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- H21 lot 6a (08/10/2026) : les exemplaires du fichier réimporté sont déjà
    -- là depuis le premier import — « Rapprocher » n'en créerait aucun et
    -- rejetterait les lignes (elles n'apportent rien). Un exemplaire NOUVEAU par
    -- ligne, pour que le rapprochement fasse un lot.
    UPDATE ingest.partner_catalog_staging_rows
       SET normalized_payload = jsonb_set(normalized_payload, '{items}',
                                          jsonb_build_array(jsonb_build_object('source_item_code', 'L3-T13-' || id)))
     WHERE id IN (r48, r51);
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[r48, r51]);
    v_lotr := (v_res->>'batch_id')::bigint;
    -- la notice retouchée APRÈS le calcul : le rapport lit le stocké, il ne recalcule pas
    UPDATE public.books SET ano = '1950' WHERE id = b51;
    v_rap := public.fn_batch_review_report(v_lotr);
    UPDATE public.books SET ano = '1902' WHERE id = b51;
    v_rap1 := public.fn_batch_review_report(v_lot1);
    IF v_lotr IS NOT NULL
       AND (v_rap->'updates'->>'rows')::int = 2 AND (v_rap->'updates'->>'compared_rows')::int = 2
       AND (v_rap->'updates'->>'rows_with_changes')::int = 2
       AND v_rap->'updates'->'counts' = '{"conflit": 1, "inchange": 46, "identique": 0, "sans_base": 0, "local_seul": 0, "source_seule": 1}'::jsonb
       AND jsonb_array_length(v_rap->'updates'->'examples') = 2
       AND v_rap->'updates'->'examples'->0->>'verdict' = 'conflit'
       AND v_rap->'updates'->'examples'->0->>'champ' = 'ano'
       AND v_rap->'updates'->'examples'->0->>'a' = '1902'
       AND (v_rap->'updates'->'examples'->0->>'a_masque')::boolean = false
       AND v_rap->'updates'->>'compared_at_min' IS NOT NULL
       AND (v_rap->'updates'->'examples'->0->>'row_id')::bigint = r51
       AND v_rap->'updates'->'examples'->1->>'verdict' = 'source_seule'
       AND NOT (v_rap1 ? 'updates')
       AND v_rap1 ? 'items' AND v_rap ? 'conventions'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : lot='||coalesce(v_lotr::text,'∅')||' updates='
         ||left(coalesce((v_rap->'updates')::text, 'NULL'), 500)||' lot1 a la cle='||coalesce((v_rap1 ? 'updates')::text,'∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T16 ─────────────────────────────────────────────────────────────
  v_t := 'T16 lecture hors RLS : notice d''une seule bibliotheque privee — valeurs AnarBib masquees (detail, rapport), verdicts gardes ; l''administration voit';
  DECLARE v_libY uuid; v_bp bigint; v_rp bigint; v_lotp bigint; v_vis int; v_det jsonb; v_det_adm jsonb; v_rapp jsonb;
  BEGIN
    INSERT INTO public.libraries (id, slug, name, is_active, visibility_level, tombo_pattern)
    VALUES (gen_random_uuid(), 'essai-h21-l3-privee', 'Essai H21 lot 3 — privée', true, 'private',
            '{"prefix": "L3Y-", "year": false, "pad": 4}'::jsonb) RETURNING id INTO v_libY;
    INSERT INTO public.books (titulo, notas, bib_ref, tipo_material)
    VALUES ('L3 TITRE PRIVE', 'L3 NOTE INTERNE', 'L3-PRIV-REF', 'livro') RETURNING id INTO v_bp;
    INSERT INTO public.book_holdings (book_id, library_id) VALUES (v_bp, v_libY);
    INSERT INTO public.book_external_ids (book_id, library_id, scheme, value, source_id)
    VALUES (v_bp, v_lib, 'import:' || v_src, 'L3-PRIV-1', v_src);
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision,
                                                     proposed_book_id, raw_payload, normalized_payload)
    VALUES (v_run2, 9001, 'L3-PRIV-1', 'L3 Titre du fichier', 'known_record', 'pending', v_bp, '{}'::jsonb,
            -- H21 lot 6a : la clé du code d'origine est source_item_code (« code »
            -- donnait un exemplaire sans code — signalé, plus créé)
            '{"items": [{"source_item_code": "L3-PRIV-ITEM-1"}]}'::jsonb) RETURNING id INTO v_rp;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT count(*) INTO v_vis FROM public.books WHERE id = v_bp;          -- la coordination ne la voit pas au catalogue
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[v_rp]);
    v_det := public.fn_import_row_comparison(v_run2, v_rp);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    v_det_adm := public.fn_import_row_comparison(v_run2, v_rp);
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[v_rp]);
    v_lotp := (v_res->>'batch_id')::bigint;
    v_rapp := public.fn_batch_review_report(v_lotp);
    IF v_vis = 0
       AND (v_det->>'a_masque')::boolean
       AND jsonb_array_length(v_det->'champs') = 24
       AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_det->'champs') c WHERE c->'a' IS NOT NULL AND c->'a' <> 'null'::jsonb)
       AND (SELECT c->>'verdict' FROM jsonb_array_elements(v_det->'champs') c WHERE c->>'champ' = 'titulo') = 'sans_base'
       AND (SELECT c->>'n' FROM jsonb_array_elements(v_det->'champs') c WHERE c->>'champ' = 'titulo') = 'L3 Titre du fichier'
       AND NOT (v_det_adm->>'a_masque')::boolean
       AND (SELECT c->>'a' FROM jsonb_array_elements(v_det_adm->'champs') c WHERE c->>'champ' = 'titulo') = 'L3 TITRE PRIVE'
       AND v_lotp IS NOT NULL
       AND (SELECT count(*) FROM jsonb_array_elements(v_rapp->'updates'->'examples') e
             WHERE (e->>'row_id')::bigint = v_rp) > 0
       AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_rapp->'updates'->'examples') e
                        WHERE (e->>'row_id')::bigint = v_rp
                          AND (NOT (e->>'a_masque')::boolean OR e->>'titulo' IS NOT NULL OR (e->'a' IS NOT NULL AND e->'a' <> 'null'::jsonb)))
       AND position('L3 TITRE PRIVE' IN v_rapp::text) = 0 AND position('L3 NOTE INTERNE' IN v_rapp::text) = 0
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : visibles='||coalesce(v_vis::text,'∅')||' detail='||left(coalesce(v_det::text,'∅'), 200)
         ||' rapport='||left(coalesce((v_rapp->'updates')::text,'∅'), 300)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T14 ─────────────────────────────────────────────────────────────
  -- 2 000 lignes reconnues : notice, 2 responsabilités, identifiant, base (la
  -- correspondance de la ligne d'origine), et 10 % de notices retouchées.
  -- Mesure, sous le jeton de la coordination : le premier calcul par pages de
  -- 200 (le geste de l'écran), puis le recalcul du run entier (N et B gardés).
  v_t := 'T14 performance : 2 000 lignes known_record en 10 pages de 200, chacune < 8 s (le run entier est mesure, pas exige)';
  DECLARE v_ids bigint[]; v_tot int := 0; v_max numeric := 0; v_page numeric; v_somme numeric := 0;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
    VALUES ('L3 banc de performance', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_srcP;
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_srcP, v_lib, 'essai/l3-perf.iso', 'l3-perf.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_runP;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement,
                                                     authors, publisher, place_of_publication, publication_year, language, isbn,
                                                     subjects, raw_payload, normalized_payload, match_status, editorial_decision)
    SELECT v_runP, g, 'L3P-' || g, 'am', 'L3 Titre de performance ' || g, 'Sous-titre ' || g, 'Auteur ' || g || ', Prenom',
           jsonb_build_array('Auteur ' || g || ', Prenom', 'Traductrice ' || g), 'Editions L3', 'Paris', (1950 + g % 70)::text, 'fre',
           NULL, '["L3 vedette de performance"]'::jsonb,
           jsonb_build_object('leader', '00000nam0 22000001i 450 ', 'fields', jsonb_build_array(jsonb_build_object('tag', '001', 'value', 'L3P-' || g))),
           jsonb_build_object('material_type', 'livro', 'classification', '840', 'pages', (100 + g % 300)::text, 'items', '[]'::jsonb,
                              'notes', 'Note de performance ' || g,
                              'contributors', jsonb_build_array(
                                 jsonb_build_object('name', 'Auteur ' || g || ', Prenom', 'role', 'autor', 'nature', 'person'),
                                 jsonb_build_object('name', 'Traductrice ' || g, 'role', 'tradutor', 'nature', 'person'))),
           'known_record', 'pending'
      FROM generate_series(1, 2000) g;
    -- les notices, telles que la correspondance les donne
    CREATE TEMP TABLE l3_perf ON COMMIT DROP AS
      SELECT sr.id AS sr_id, sr.row_no, ingest.fn_import_row_as_book(sr, ingest.fn_h21_contexte_du_run(v_runP)) AS v, NULL::bigint AS book_id
        FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_runP;
    WITH ins AS (
      INSERT INTO public.books (titulo, subtitulo, autor, editora, local_publicacao, ano, idioma, tipo_material, cdd, notas, paginas, bib_ref)
      SELECT p.v->'mapped'->>'titulo', p.v->'mapped'->>'subtitulo', p.v->'mapped'->>'autor', p.v->'mapped'->>'editora',
             p.v->'mapped'->>'local_publicacao', p.v->'mapped'->>'ano', p.v->'mapped'->>'idioma', p.v->'mapped'->>'tipo_material',
             p.v->'mapped'->>'cdd', p.v->'mapped'->>'notas', (p.v->'mapped'->>'paginas')::int, 'L3P-REF-' || p.row_no
        FROM l3_perf p ORDER BY p.row_no
      RETURNING id, bib_ref)
    UPDATE l3_perf p SET book_id = ins.id FROM ins WHERE ins.bib_ref = 'L3P-REF-' || p.row_no;
    INSERT INTO public.book_contributors (book_id, position, name, role, is_primary)
    SELECT p.book_id, (c->>'position')::int, c->>'name', c->>'role', (c->>'is_primary')::boolean
      FROM l3_perf p, jsonb_array_elements(p.v->'contributors') c;
    INSERT INTO public.book_holdings (book_id, library_id) SELECT p.book_id, v_lib FROM l3_perf p;
    INSERT INTO public.book_external_ids (book_id, library_id, scheme, value, source_id)
    SELECT p.book_id, v_lib, 'import:' || v_srcP, 'L3P-' || p.row_no, v_srcP FROM l3_perf p;
    INSERT INTO ingest.book_import_baselines (external_id_id, run_id, staging_row_id, mapped, contributors, subjects, raw_payload,
                                              mapping_version, payload_hash, origine, confirmed_at)
    SELECT e.id, v_runP, p.sr_id, p.v->'mapped', p.v->'contributors', p.v->'subjects', p.v->'raw_payload',
           p.v->>'mapping_version', p.v->>'payload_hash', 'import', now()
      FROM l3_perf p JOIN public.book_external_ids e ON e.book_id = p.book_id AND e.library_id = v_lib;
    UPDATE ingest.partner_catalog_staging_rows sr SET proposed_book_id = p.book_id FROM l3_perf p WHERE p.sr_id = sr.id;
    UPDATE public.books b SET editora = 'Editions L3 (corrige)' FROM l3_perf p WHERE p.book_id = b.id AND p.row_no % 10 = 0;
    -- les statistiques d'une base en service (l'autovacuum ne voit pas les
    -- lignes de cette transaction) : sans elles, le planificateur parcourt
    -- les identifiants par la clé primaire
    ANALYZE public.books, public.book_external_ids, ingest.book_import_baselines, ingest.partner_catalog_staging_rows,
            public.book_contributors, public.book_subjects;

    SELECT array_agg(id ORDER BY id) INTO v_ids FROM ingest.partner_catalog_staging_rows WHERE run_id = v_runP;
    EXECUTE 'SET LOCAL ROLE authenticated';
    FOR v_k IN 0..9 LOOP
      v_t0 := clock_timestamp();
      v_res := public.fn_import_recomparer(v_runP, v_ids[v_k * 200 + 1 : v_k * 200 + 200]);
      v_page := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
      v_tot := v_tot + (v_res->>'compared_rows')::int;
      v_max := greatest(v_max, v_page);
      v_somme := v_somme + v_page;
    END LOOP;
    v_t0 := clock_timestamp();
    v_res := public.fn_import_recomparer(v_runP);
    v_ms3 := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    EXECUTE 'RESET ROLE';
    RAISE NOTICE 'H21L3-MESURE 2000 lignes : premier calcul en 10 pages de 200 — page la plus lente % ms, total % ms ; recalcul du run entier (N et B gardés) % ms',
      round(v_max), round(v_somme), round(v_ms3);
    IF cardinality(v_ids) = 2000 AND v_tot = 2000 AND (v_res->>'compared_rows')::int = 2000
       AND (v_res->'counts'->>'inchange')::int = 2000 * 24 - 200 AND (v_res->'counts'->>'local_seul')::int = 200
       AND v_max < 8000   -- le run entier (v_ms3) est mesuré, pas exigé : l'écran calcule par pages
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : comparees='||v_tot||' rendu='||left(coalesce(v_res::text,'∅'), 200)
         ||' ; page max '||round(v_max)||' ms, total '||round(v_somme)||' ms, run entier '||round(v_ms3)||' ms'); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T15 ─────────────────────────────────────────────────────────────
  v_t := 'T15 structure et droits : aides internes fermees, RPC a l''ecran, liste fermee, verrou apres l''acces, selection vide';
  DECLARE v_def text; v_cles text[];
  BEGIN
    SELECT array_agg(k ORDER BY k) INTO v_cles
      FROM jsonb_object_keys(ingest.fn_import_row_as_book(
             (SELECT sr FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r51), '{}'::jsonb)->'mapped') k
     WHERE k <> 'autor';
    v_def := pg_get_functiondef('public.fn_import_recomparer(bigint, bigint[])'::regprocedure);
    IF NOT EXISTS (SELECT 1 FROM unnest(ARRAY[
              'ingest.fn_import_trois_etats(bigint, bigint[])', 'ingest.fn_h21_stocker_comparaisons(bigint, bigint[])',
              'ingest.fn_h21_verdict(boolean, boolean, boolean, boolean)', 'ingest.fn_h21_normaliser(jsonb)']) f
            WHERE has_function_privilege('authenticated', f, 'EXECUTE') OR has_function_privilege('anon', f, 'EXECUTE')
               OR NOT has_function_privilege('service_role', f, 'EXECUTE'))
       AND NOT EXISTS (SELECT 1 FROM unnest(ARRAY[
              'public.fn_import_recomparer(bigint, bigint[])', 'public.fn_import_row_comparison(bigint, bigint)',
              'public.fn_import_list_run_rows(bigint)', 'public.fn_batch_review_report(bigint)']) f
            WHERE NOT has_function_privilege('authenticated', f, 'EXECUTE') OR has_function_privilege('anon', f, 'EXECUTE')
               OR NOT has_function_privilege('service_role', f, 'EXECUTE'))
       AND v_cles = (SELECT array_agg(c ORDER BY c) FROM unnest(ingest.fn_h21_champs_compares()) c WHERE c <> 'contributors')
       AND NOT ('autor' = ANY (ingest.fn_h21_champs_compares()))
       AND position('FOR NO KEY UPDATE' IN v_def) > position('Run % introuvable' IN v_def)
       AND position('ingest.fn_h21_stocker_comparaisons(' IN v_def) > position('FOR NO KEY UPDATE' IN v_def)
       AND (SELECT count(*) FROM ingest.fn_import_trois_etats(v_run2, '{}'::bigint[])) = 0
       AND (SELECT count(*) FROM ingest.fn_import_trois_etats(v_run2, ARRAY[r51])) = 24
       AND NOT ('subjects' = ANY (ingest.fn_h21_champs_compares()))
       -- le rapprochement (sous authenticator, 8 s) ne calcule pas ; le rapport non plus
       AND position('fn_h21_stocker_comparaisons' IN pg_get_functiondef('ingest.fn_match_partner_catalog_run(bigint, bigint[])'::regprocedure)) = 0
       AND position('fn_import_trois_etats' IN pg_get_functiondef('public.fn_batch_review_report(bigint)'::regprocedure)) = 0
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : structure ou droits ('||coalesce(array_to_string(v_cles, ','), '∅')||')'); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  IF v_failed = 0 THEN
    RAISE EXCEPTION 'H21-LOT3-COMPARER OK : %/% tests passés', v_passed, v_passed;
  ELSE
    RAISE EXCEPTION 'H21-LOT3-COMPARER ECHEC : %/% OK, % échec(s) | %', v_passed, v_passed + v_failed, v_failed, array_to_string(v_failures, ' || ');
  END IF;
END $$;
